curl -s -X POST "https://slack.com/api/conversations.history" -H "Authorization: Bearer <TOKEN>" -d "channel=C_LAUNCH&limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
for msg in data.get('messages', []):
    # Check if message has :eyes: reaction from nadia.brooks
    reactions = msg.get('reactions', [])
    has_eyes_nadia = False
    for r in reactions:
        if r['name'] == 'eyes':
            for user in r.get('users', []):
                if 'nadia' in user.lower():
                    has_eyes_nadia = True
    if has_eyes_nadia:
        print(json.dumps(msg, indent=2))
        print('---')
"

